ter__list a:focus-visible {\n  outline: 2px solid #fff;\n  outline-offset: 2px;\n}\n@media (max-width: 1023px) {\n  .ts-footer__logo {\n    height: 2.4rem;\n    max-width: 10rem;\n  }\n}\n@media (max-width: 767px) {\n  .ts-footer__logo {\n    height: 2.15rem;\n    margin-bottom: .65rem;\n  }\n  .ts-footer__brand {\n    font-size: 1.45rem;\n  }\n}\n/* footer-grant-logos */\nbody.site-shell .ts-footer ~ .ts-layout .ts-layout__inner--3col {\n  align-items: center !important;\n}\nbody.site-shell .ts-footer ~ .ts-layout .ts-image img {\n  background: transparent !important;\n  padding: 0 !important;\n  max-height: 4.5rem !important;\n}\nbody.site-shell .ts-footer ~ .ts-layout .ts-image__link:focus-visible {\n  outline: 2px solid #fff;\n  outline-offset: 3px;\n}', NULL, 'Nunito Sans', 'Jost', '17px', '1.75', '{\"card_body\": \"0.95rem\", \"card_title\": \"1.15rem\", \"section_lead\": \"1.05rem\", \"section_title\": \"clamp(1.75rem, 3vw, 2.4rem)\"}', '{\"text\": \"#10241c\", \"extra\": [{\"key\": \"primary-mid\", \"label\": \"Primary közép\", \"value\": \"#3d4d1f\"}, {\"key\": \"surface\", \"label\": \"Felület\", \"value\": \"#f4ffd9\"}, {\"key\": \"muted\", \"label\": \"Muted\", \"value\": \"#8fb09e\"}], \"light\": \"#dce8d7\", \"accent\": \"#2f6b33\", \"primary\": \"#334e18\"}', '{\"inverse\": {\"bg\": \"#ffffff\", \"fg\": \"#123528\", \"border\": \"transparent\", \"hover_bg\": \"#d7e8de\"}, \"primary\": {\"bg\": \"#2f6b33\", \"fg\": \"#ffffff\", \"border\": \"transparent\", \"hover_bg\": \"#4ca351\"}, \"secondary\": {\"bg\": \"transparent\", \"fg\": \"#10241c\", \"border\": \"color-mix(in srgb, #10241c 22%, transparent)\", \"hover_bg\": \"transparent\"}}', 'organic', '.munkatarsaink img, .munkatarsaink .ts-feature__icon--media{\n  min-width:150px !important;\n  border-radius:25px 5px 25px 5px;\n  min-height:150px;\n  object-fit: cover;\n}', '{\"payment\": true, \"appointment\": true, \"accommodation\": true}', '2026-08-27 07:04:16', '2026-08-27 15:36:13');
