INSERT INTO `site_pages` (`id`, `title`, `slug`, `html`, `css`, `grapes_data`, `seo`, `is_published`, `is_homepage`, `sort_order`, `created_at`, `updated_at`) VALUES (2, 'Munkáink', 'munkaink', '<section data-gjs-type=\"ts-layout-1col\" data-layout=\"boxed\" data-section-width=\"content\" data-extra-class=\"\" id=\"it9h7\" data-logo-height=\"40\" data-logo-max-width=\"180\" data-menu-breakpoint=\"phone\" class=\"ts-layout\"><div class=\"ts-layout__inner\"><div class=\"ts-layout__col\"><p class=\"ts-layout__placeholder\">Húzza ide a blokkokat</p><section data-gjs-type=\"ts-text\" data-overlay=\"0\" data-overlay-color=\"\" data-layout=\"left\" data-title=\"html:Munk%C3%A1ink\" data-show-title=\"1\" data-body=\"html:%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3E%3Cstrong%3EMunk%C3%A1ink%20az%20%C3%A9vek%20sor%C3%A1n%20megval%C3%B3sult%20projektek%20soksz%C3%ADn%C5%B1s%C3%A9g%C3%A9t%20%C3%A9s%20szakmai%20szeml%C3%A9let%C3%BCnk%20k%C3%B6vetkezetess%C3%A9g%C3%A9t%20t%C3%BCkr%C3%B6zik.%3C%2Fstrong%3E%20%20%0AHisz%C3%BCnk%20abban%2C%20hogy%20minden%20%C3%A9p%C3%ADt%C3%A9szeti%20feladat%20egyedi%20p%C3%A1rbesz%C3%A9d%20a%20helysz%C3%ADnnel%2C%20a%20funkci%C3%B3val%20%C3%A9s%20az%20%C3%BCgyf%C3%A9l%20elk%C3%A9pzel%C3%A9seivel.%20Referenci%C3%A1ink%20k%C3%B6z%C3%B6tt%20lak%C3%B3%C3%A9p%C3%BCletek%2C%20k%C3%B6z%C3%A9p%C3%BCletek%20%C3%A9s%20egyedi%20tervez%C3%A9s%C5%B1%20terek%20egyar%C3%A1nt%20megtal%C3%A1lhat%C3%B3k%2C%20melyekben%20a%20gondos%20tervez%C3%A9s%2C%20az%20eszt%C3%A9tikai%20ig%C3%A9nyess%C3%A9g%20%C3%A9s%20a%20hossz%C3%BA%20t%C3%A1v%C3%BA%20haszn%C3%A1lhat%C3%B3s%C3%A1g%20ir%C3%A1nti%20elk%C3%B6telezetts%C3%A9g%C3%BCnk%20egyar%C3%A1nt%20megjelenik.%3C%2Fspan%3E%3C%2Fp%3E%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3EAz%20al%C3%A1bbiakban%20v%C3%A1logat%C3%A1st%20tal%C3%A1l%20irod%C3%A1nk%20kiemelt%20projektjeib%C5%91l.%3C%2Fspan%3E%3C%2Fp%3E\" data-show-body=\"1\" data-extra-class=\"\" id=\"i3weh\" data-logo-height=\"40\" data-logo-max-width=\"180\" data-menu-breakpoint=\"phone\" class=\"ts-text\" style=\"position: relative;\"><div data-ts-bg-overlay=\"\" data-gjs-name=\"Overlay\" class=\"ts-surface-overlay\" id=\"i5oln\" style=\"pointer-events: none; opacity: 0; background-image: none; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: var(--color-primary); position: absolute; inset: 0px; z-index: 1;\"></div><div class=\"ts-text__inner\" style=\"position: relative; z-index: 2;\"><h2 data-ts-text=\"title\">Munkáink</h2><p data-ts-text=\"body\"></p><p><span id=\"imhmk\"><strong>Munkáink az évek során megvalósult projektek sokszínűségét és szakmai szemléletünk következetességét tükrözik.</strong>  \nHiszünk abban, hogy minden építészeti feladat egyedi párbeszéd a helyszínnel, a funkcióval és az ügyfél elképzeléseivel. Referenciáink között lakóépületek, középületek és egyedi tervezésű terek egyaránt megtalálhatók, melyekben a gondos tervezés, az esztétikai igényesség és a hosszú távú használhatóság iránti elkötelezettségünk egyaránt megjelenik.</span></p><p><span id=\"ip6oo\">Az alábbiakban válogatást talál irodánk kiemelt projektjeiből.</span></p><p></p></div></section></div></div></section><section data-gjs-type=\"ts-ba-gallery\" data-title=\"html:Munk%C3%A1ink\" data-show-title=\"0\" data-items=\"[{&quot;image&quot;:&quot;/images/site/74901.jpg&quot;,&quot;image_after&quot;:&quot;/images/site/74901-2.jpg&quot;,&quot;alt&quot;:&quot;&quot;},{&quot;image&quot;:&quot;/images/site/74901.jpg&quot;,&quot;image_after&quot;:&quot;&quot;,&quot;alt&quot;:&quot;&quot;},{&quot;image&quot;:&quot;/images/site/74901.jpg&quot;,&quot;image_after&quot;:&quot;/images/site/hero-1.jpg&quot;,&quot;alt&quot;:&quot;&quot;}]\" data-extra-class=\"\" id=\"igduz\" data-logo-height=\"40\" data-logo-max-width=\"180\" data-menu-breakpoint=\"phone\" class=\"ts-ba-gallery\"><div class=\"ts-ba-gallery__inne