INSERT INTO `site_pages` (`id`, `title`, `slug`, `html`, `css`, `grapes_data`, `seo`, `is_published`, `is_homepage`, `sort_order`, `created_at`, `updated_at`) VALUES (3, 'Iroda', 'iroda', '<section data-gjs-type=\"ts-split\" data-overlay=\"0\" data-overlay-color=\"\" data-layout=\"image-right\" data-media-url=\"/images/site/hero2.jpg\" data-eyebrow=\"Bemutatkozás\" data-show-eyebrow=\"1\" data-title=\"html:F%C3%BCgefa%20%C3%89p%C3%ADt%C3%A9sziroda\" data-show-title=\"1\" data-body=\"html:%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3E%3Cstrong%3EIrod%C3%A1nk%20elk%C3%B6telezetten%20dolgozik%20azon%2C%20hogy%20minden%20projektben%20a%20funkcionalit%C3%A1s%2C%20az%20eszt%C3%A9tika%20%C3%A9s%20a%20szakmai%20precizit%C3%A1s%20egyens%C3%BAlya%20val%C3%B3suljon%20meg.%3C%2Fstrong%3E%20%20%0AHisz%C3%BCnk%20a%20szem%C3%A9lyes%20egy%C3%BCttm%C5%B1k%C3%B6d%C3%A9sben%2C%20a%20gondos%20tervez%C3%A9sben%20%C3%A9s%20abban%2C%20hogy%20a%20j%C3%B3l%20%C3%A1tgondolt%20%C3%A9p%C3%ADt%C3%A9szeti%20megold%C3%A1sok%20hossz%C3%BA%20t%C3%A1von%20hat%C3%A1rozz%C3%A1k%20meg%20az%20%C3%A9lettereket.%20Csapatunk%20sokr%C3%A9t%C5%B1%20szakmai%20tapasztalattal%2C%20kreat%C3%ADv%20szeml%C3%A9lettel%20%C3%A9s%20felel%C5%91ss%C3%A9gteljes%20hozz%C3%A1%C3%A1ll%C3%A1ssal%20t%C3%A1mogatja%20%C3%BCgyfeleinket%20a%20koncepci%C3%B3alkot%C3%A1st%C3%B3l%20eg%C3%A9szen%20a%20megval%C3%B3s%C3%ADt%C3%A1sig.%3C%2Fspan%3E%3C%2Fp%3E%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3EAz%20al%C3%A1bbiakban%20megismerheti%20koll%C3%A9g%C3%A1inkat%2C%20akik%20nap%20mint%20nap%20az%C3%A9rt%20dolgoznak%2C%20hogy%20minden%20projekt%20egyedi%20%C3%A9s%20id%C5%91t%C3%A1ll%C3%B3%20%C3%A9rt%C3%A9ket%20k%C3%A9pviseljen.%3C%2Fspan%3E%3C%2Fp%3E\" data-show-body=\"1\" data-button-label=\"Tudjon meg többet\" data-show-button=\"0\" data-button-href=\"#\" data-button-style=\"primary\" data-extra-class=\"\" id=\"in6pj\" data-logo-height=\"40\" data-logo-max-width=\"180\" data-menu-breakpoint=\"phone\" class=\"ts-split\" style=\"position: relative;\"><div data-ts-bg-overlay=\"\" data-gjs-name=\"Overlay\" class=\"ts-surface-overlay\" id=\"iy1ho\" style=\"pointer-events: none; opacity: 0; background-image: none; background-position-x: ; background-position-y: ; background-size: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: var(--color-primary); position: absolute; inset: 0px; z-index: 1;\"></div><div class=\"ts-split__inner\" style=\"position: relative; z-index: 2;\"><div class=\"ts-split__copy\"><p data-ts-text=\"eyebrow\" class=\"ts-split__eyebrow\">Bemutatkozás</p><h2 data-ts-text=\"title\">Fügefa Építésziroda</h2><p data-ts-text=\"body\"></p><p><span id=\"i9x0e\"><strong>Irodánk elkötelezetten dolgozik azon, hogy minden projektben a funkcionalitás, az esztétika és a szakmai precizitás egyensúlya valósuljon meg.</strong>  \nHiszünk a személyes együttműködésben, a gondos tervezésben és abban, hogy a jól átgondolt építészeti megoldások hosszú távon határozzák meg az élettereket. Csapatunk sokrétű szakmai tapasztalattal, kreatív szemlélettel és felelősségteljes hozzáállással támogatja ügyfeleinket a koncepcióalkotástól egészen a megvalósításig.</span></p><p><span id=\"i2hy5\">Az alábbiakban megismerheti kollégáinkat, akik nap mint nap azért dolgoznak, hogy minden projekt egyedi és időtálló értéket képviseljen.</span></p><p></p><a data-ts-btn=\"button_style\" data-ts-text=\"button_label\" data-ts-href=\"button_href\" href=\"#\" class=\"ts-btn ts-btn--primary\">Tudjon meg többet</a></div><div class=\"ts-split__media\"><img data-ts-bg-image=\"\" src=\"/images/site/hero2.jpg\" alt=\"\"></div></div></section><section data-gjs-type=\"ts-features\" data-overlay=\"0\" data-overlay-color=\"\" data-layout=\"center\" data-title=\"html:Munkat%C3%A1rsak\" data-show-title=\"1\" data-columns=\"3\" data-items=\"[{&quot;icon&quot;:&quot;none&quot;,&quot;image&quot;:&quot;/images/site/woman-1.jpg&quot;,&quot;title&quot;:&quot;M