INSERT INTO `site_pages` (`id`, `title`, `slug`, `html`, `css`, `grapes_data`, `seo`, `is_published`, `is_homepage`, `sort_order`, `created_at`, `updated_at`) VALUES (5, 'Időpontfoglalás', 'idopontfoglalas', '<section data-ts-dynamic=\"appointment-booking\" data-gjs-type=\"ts-appointment-booking\" data-layout=\"grid\" data-title=\"Időpontfoglalás\" data-show-title=\"1\" data-text=\"html:%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3E%3Cstrong%3EAz%20%C3%A9p%C3%ADt%C3%A9szeti%20tervez%C3%A9s%20minden%20projekt%20eset%C3%A9ben%20szem%C3%A9lyes%20egyeztet%C3%A9ssel%20kezd%C5%91dik.%3C%2Fstrong%3E%20%20%0AIrod%C3%A1nkban%20nagy%20hangs%C3%BAlyt%20fektet%C3%BCnk%20arra%2C%20hogy%20m%C3%A1r%20az%20els%C5%91%20tal%C3%A1lkoz%C3%B3n%20megismerj%C3%BCk%20az%20elk%C3%A9pzel%C3%A9seket%2C%20a%20telek%20adotts%C3%A1gait%20%C3%A9s%20a%20m%C5%B1szaki%E2%80%91eszt%C3%A9tikai%20ig%C3%A9nyeket.%20A%20konzult%C3%A1ci%C3%B3%20sor%C3%A1n%20%C3%A1tbesz%C3%A9lj%C3%BCk%20a%20lehets%C3%A9ges%20ir%C3%A1nyokat%2C%20a%20tervez%C3%A9si%20folyamat%20l%C3%A9p%C3%A9seit%20%C3%A9s%20a%20projekt%20v%C3%A1rhat%C3%B3%20%C3%BCtemez%C3%A9s%C3%A9t%2C%20hogy%20biztos%20alapokra%20%C3%A9p%C3%ADthess%C3%BCk%20a%20k%C3%B6z%C3%B6s%20munk%C3%A1t.%3C%2Fspan%3E%3C%2Fp%3E%3Cp%3E%3Cspan%20style%3D%22white-space%3A%20pre-wrap%3B%22%3EK%C3%A9rj%C3%BCk%2C%20v%C3%A1lasszon%20id%C5%91pontot%20az%20al%C3%A1bbi%20napt%C3%A1rban%2C%20hogy%20szem%C3%A9lyesen%20is%20elind%C3%ADthassuk%20a%20k%C3%B6z%C3%B6s%20tervez%C3%A9st.%3C%2Fspan%3E%3C%2Fp%3E\" data-show-text=\"1\" data-button=\"Időpont foglalása\" data-show-button=\"1\" data-limit=\"12\" data-extra-class=\"\" data-logo-height=\"40\" data-logo-max-width=\"180\" data-menu-breakpoint=\"phone\" id=\"i218\" class=\"ts-dyn-block ts-dyn-appointment\"><div class=\"ts-dyn-appointment__inner\"><h2 data-ts-text=\"title\" class=\"ts-dyn-appointment__title\">Időpontfoglalás</h2><p data-ts-text=\"text\" class=\"ts-dyn-appointment__text\"></p><p><span id=\"io11k\"><strong>Az építészeti tervezés minden projekt esetében személyes egyeztetéssel kezdődik.</strong>  \nIrodánkban nagy hangsúlyt fektetünk arra, hogy már az első találkozón megismerjük az elképzeléseket, a telek adottságait és a műszaki‑esztétikai igényeket. A konzultáció során átbeszéljük a lehetséges irányokat, a tervezési folyamat lépéseit és a projekt várható ütemezését, hogy biztos alapokra építhessük a közös munkát.</span></p><p><span id=\"id6tg\">Kérjük, válasszon időpontot az alábbi naptárban, hogy személyesen is elindíthassuk a közös tervezést.</span></p><p></p><div class=\"ts-dyn-appointment__grid\"><article class=\"ts-dyn-appointment__card\"><p class=\"ts-dyn-appointment__role\">Építészmérnök</p><h3>Maksai-Szamosi Ildikó</h3><p>Bemutatkozás</p><p class=\"ts-dyn-appointment__meta\">60 perces időpontok</p><a href=\"/idopontfoglalas/maksai-szamosi-ildiko\" data-ts-text=\"button\" class=\"ts-dyn-appointment__cta\">Időpont foglalása</a></article></div></div></section>', '* { box-sizing: border-box; } body {margin: 0;}.ts-dyn-block{color:var(--color-text);font-family:var(--font-sans,Karla,sans-serif);}.ts-dyn-appointment{padding-top:3.5rem;padding-left:1.5rem;padding-right:1.5rem;padding-bottom:3.5rem;}.ts-dyn-appointment__inner{max-width:72rem;margin-top:0px;margin-left:auto;margin-right:auto;margin-bottom:0px;}.ts-dyn-appointment__title{font-size:clamp(1.75rem, 3vw, 2.4rem);margin-top:0px;font-family:var(--font-display,Literata,serif);margin-left:0px;margin-right:0px;margin-bottom:0.5rem;}.ts-dyn-appointment__text{opacity:0.75;margin-top:0px;line-height:1.6;margin-left:0px;margin-right:0px;margin-bottom:1.5rem;}.ts-dyn-appointment__grid{display:grid;row-gap:1.25rem;column-gap:1.25rem;grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));}.ts-dyn-appointment__card{padding-top:1.25rem;padding-left:1.25rem;padding-right:1.25rem;padding-bottom:1.25rem;background-clip:initial;background-size:initial;background-color:rgb(255, 255, 255);background-image:initial;backg